// Constructed sets exist to prove the FAILURE MODES. Real reviews cannot do that,
// because you cannot prove a model does not invent contradictions using data that has some.
const SETS = {
  // A: genuine two-sided split on ONE theme -> must report a split with counts
  A_genuine_split: [
    {id:"a1", rating:5, text:"Ordered a capacitor Tuesday, it was on my doorstep Wednesday. Incredibly fast."},
    {id:"a2", rating:5, text:"Shipping was quicker than expected, had the part next day."},
    {id:"a3", rating:5, text:"Fast delivery, no complaints at all."},
    {id:"a4", rating:2, text:"Took eleven days to get my order. Way too slow."},
    {id:"a5", rating:2, text:"Shipping is painfully slow, I could have driven there faster."},
    {id:"a6", rating:1, text:"Still waiting on a part I ordered two weeks ago. Terrible shipping."}
  ],
  // B: LOPSIDED - 9 happy, 1 substantive complaint. The 1 must SURVIVE, not get averaged away.
  B_lopsided: [
    {id:"b1", rating:5, text:"Great counter staff, knew exactly what I needed."},
    {id:"b2", rating:5, text:"Always have the parts in stock. Lifesaver."},
    {id:"b3", rating:5, text:"Good prices and friendly people."},
    {id:"b4", rating:5, text:"These guys know HVAC. Very helpful."},
    {id:"b5", rating:5, text:"In and out in five minutes with the right part."},
    {id:"b6", rating:5, text:"Best parts house in the area."},
    {id:"b7", rating:4, text:"Solid selection, helpful staff."},
    {id:"b8", rating:5, text:"They had the motor nobody else had."},
    {id:"b9", rating:5, text:"Quick, easy, knowledgeable."},
    {id:"b10", rating:1, text:"They sold me a used compressor as new. When I brought it back they refused the return and argued with me for twenty minutes."}
  ],
  // C: ALL AGREE - there is NOTHING to contradict. If it reports a split, it invented one.
  C_all_agree: [
    {id:"c1", rating:5, text:"Fantastic service, super helpful staff."},
    {id:"c2", rating:5, text:"The team here is great, really knowledgeable."},
    {id:"c3", rating:5, text:"Staff went out of their way to help me find the part."},
    {id:"c4", rating:5, text:"Very friendly and helpful people at the counter."},
    {id:"c5", rating:5, text:"Excellent help from the guys working there."}
  ],
  // D: DIFFERENT dimensions. Price complaints + quality praise is NOT a contradiction.
  D_different_dimensions: [
    {id:"d1", rating:3, text:"Parts are good quality but honestly overpriced compared to online."},
    {id:"d2", rating:3, text:"Quality is solid, prices are steep."},
    {id:"d3", rating:2, text:"Way too expensive for what it is."},
    {id:"d4", rating:5, text:"Very well made parts, they last."},
    {id:"d5", rating:5, text:"Quality is excellent, never had one fail."}
  ],
  // E: MIXED WITHIN a single review. One reviewer, two opposite signals.
  E_mixed_within_one: [
    {id:"e1", rating:3, text:"The staff were genuinely great and helped me troubleshoot, but I waited almost an hour at the counter before anyone got to me."},
    {id:"e2", rating:3, text:"Love the people here, hate the wait. Always a line."},
    {id:"e3", rating:4, text:"Knowledgeable crew but they are understaffed, took forever."}
  ],
  // Paste real reviews here to smoke-test realism (the live path uses the GBP node instead)
  REAL_paste: []
};

// >>> pick which case to run <<<
const WHICH = "E_mixed_within_one";

const rows = SETS[WHICH] || [];
if (!rows.length) throw new Error("Test set is empty: " + WHICH);
return rows.map(r => ({ json: {
  review_id: r.id,
  rating: r.rating,
  text: r.text,
  author: "test",
  created: null,
  source: "TEST:" + WHICH
}}));

// Accepts BOTH shapes: the GBP node output and the test-set output.
// GBP starRating is an ENUM STRING ("FIVE"), not a number. That trips people up.
const WORDS = { ONE:1, TWO:2, THREE:3, FOUR:4, FIVE:5 };
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.text !== undefined && j.review_id !== undefined) { out.push({ json: j }); continue; } // already normalized
  const text = (j.comment || "").trim();
  if (!text) continue;                                   // star-only ratings carry no feedback content
  out.push({ json: {
    review_id: j.reviewId || j.name || String(out.length),
    rating: WORDS[j.starRating] || null,
    text,
    author: (j.reviewer && j.reviewer.displayName) || "anonymous",
    created: j.createTime || null,
    replied: !!(j.reviewReply && j.reviewReply.comment),
    source: "GBP"
  }});
}
if (!out.length) throw new Error("No reviews with text found.");
return out;

// FIXED taxonomy. If themes are free text, "shipping" / "delivery" / "shipping speed"
// become three buckets and every count downstream is garbage.
const THEMES = ["price_value","product_quality","stock_availability","staff_service","wait_time",
                "shipping_delivery","returns_warranty","expertise","facility","communication"];

return $input.all().map(item => {
  const r = item.json;
  const prompt =
`Classify ONE customer review for an HVAC parts retailer.

REVIEW (rating: ${r.rating === null ? "not given" : r.rating + "/5"}):
"""
${r.text}
"""

Allowed themes (use ONLY these exact strings): ${THEMES.join(", ")}

Rules:
- Return every theme the review actually speaks to. Usually 1-3. Never invent a theme it does not mention.
- A single review CAN carry opposite sentiments on different themes. Report each separately, honestly.
- sentiment must be exactly "positive", "negative", or "mixed".
- "mixed" only when the reviewer is genuinely torn about that SAME theme.
- quote must be a short verbatim span copied from the review, not a paraphrase.
- If the review says nothing substantive, return an empty findings array.

Output ONLY raw JSON, no markdown fence, exactly:
{"findings":[{"theme":"<one allowed theme>","sentiment":"positive|negative|mixed","quote":"<verbatim span>"}]}`;
  return { json: { ...r, prompt } };
});

// Pair each model response back to its review by index, and fail LOUDLY rather than
// silently dropping a review (a silently dropped negative is how you lose the signal).
const src = $('Build Classify Prompt').all();
const ALLOWED = new Set(["price_value","product_quality","stock_availability","staff_service","wait_time",
                         "shipping_delivery","returns_warranty","expertise","facility","communication"]);
const grab = (j) => {
  if (typeof j === "string") return j;
  if (Array.isArray(j?.content)) return j.content.map(c => c?.text || "").join("");
  return j?.content?.[0]?.text || j?.text || j?.message?.content || j?.output || "";
};
const out = [];
$input.all().forEach((item, i) => {
  const raw = String(grab(item.json) || "").replace(/```json|```/g, "").trim();
  const review = (src[i] && src[i].json) || {};
  let findings = [], parse_error = null;
  try {
    const m = raw.match(/\{[\s\S]*\}/);
    const obj = JSON.parse(m ? m[0] : raw);
    findings = Array.isArray(obj.findings) ? obj.findings : [];
  } catch (e) { parse_error = String(e.message || e); }
  // drop anything outside the taxonomy so a hallucinated theme cannot pollute the counts
  let clean = findings.filter(f => f && ALLOWED.has(f.theme) &&
                                   ["positive","negative","mixed"].includes(f.sentiment));

  // QUOTE VERIFICATION (added 2026-07-22, after a real fabrication).
  // The classifier stitched two fragments of one review together in REVERSE order and
  // stored the result as a verbatim quote. The writer downstream copied it faithfully,
  // so every rule about exact quoting was obeyed and the report still carried words no
  // customer wrote. Asking the model to be careful is not a control. Checking is.
  // A failed quote does NOT discard the finding: the theme and sentiment are still
  // usable signal. Only the untrustworthy words are dropped.
  const canon = (s) => String(s == null ? "" : s)
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/\s+/g, " ")
    .trim();
  const haystack = canon(review.text);
  let quotes_rejected = 0;
  clean = clean.map(f => {
    if (!f.quote) return f;
    const q = canon(f.quote).replace(/^["']|["'.,;:!?]+$/g, "");
    if (q.length >= 4 && haystack.includes(q)) return f;
    quotes_rejected++;
    return { ...f, quote: null, quote_rejected: canon(f.quote) };
  });
  out.push({ json: {
    review_id: review.review_id, rating: review.rating, text: review.text,
    author: review.author, source: review.source,
    created: review.created ?? null,
    findings: clean,
    dropped: findings.length - clean.length,
    quotes_rejected,
    parse_error
  }});
});
return out;

// ============ THE DETERMINISTIC CORE ============
// Contradictions are DETECTED HERE, in arithmetic, not asked of a model.
// If every review agrees, there is mathematically nothing to report and the
// writer downstream is told so explicitly. That is what stops invented conflict.
const MIN_SIDE = 2;      // need >= this many reviews on BOTH sides to call it a real split
const MIN_SHARE = 0.30;  // ...AND the minority side must be >= this share of the theme
const rows = $input.all().map(i => i.json);

const themes = {};
let parse_errors = 0;
for (const r of rows) {
  if (r.parse_error) parse_errors++;
  for (const f of (r.findings || [])) {
    const t = themes[f.theme] || (themes[f.theme] = { theme: f.theme, positive: [], negative: [], mixed: [] });
    t[f.sentiment].push({ review_id: r.review_id, rating: r.rating,
                          quote: f.quote, created: r.created || null });
  }
}

const summary = Object.values(themes).map(t => {
  const pos = t.positive.length, neg = t.negative.length, mix = t.mixed.length;
  const total = pos + neg + mix;
  // FIXED 2026-07-20 (found on 58 real reviews): absolute counts alone do not scale.
  // staff_service came in 32 pos / 4 neg and got published as a "disagreement".
  // 32 vs 4 is consensus with outliers, not a divide. A split now also needs the
  // minority side to hold at least MIN_SHARE of the theme. Those 4 negatives are
  // not lost, they fall through to minority_flags below.
  const share = total ? Math.min(pos, neg) / (pos + neg || 1) : 0;
  const is_split = pos >= MIN_SIDE && neg >= MIN_SIDE && share >= MIN_SHARE;
  // FIXED 2026-07-20: the old rule required pos>=3, so a WHOLLY NEGATIVE low-volume theme
  // (0 positive, 1 furious customer) fell through silently. That is the exact signal we
  // most need to surface. Now: ANY negative not already captured as a split must surface.
  const minority_negative = neg > 0 && !is_split;

  // SEVERITY, so the owner reads the worst thing first instead of an 8-item list.
  // Four signals, all arithmetic: how many complained, how concentrated it is,
  // whether anything positive offsets it, and how angry the complainers were.
  const negStars = t.negative.map(n => n.rating).filter(r => typeof r === "number");
  const avgNegStar = negStars.length ? negStars.reduce((s, r) => s + r, 0) / negStars.length : null;
  // REBALANCED: the first version used neg*10, so raw count swamped proportion and
  // staff_service (4 bad of 35) outranked wait_time (2 bad of 3). For a small business,
  // "what share of people who mentioned this were unhappy" is the sharper signal, so
  // concentration carries the most weight and volume is capped.
  let severity = Math.round(40 * (neg / (total || 1)));        // concentration, 0-40
  severity += Math.round(20 * Math.min(1, neg / 5));           // volume, capped at 20
  if (pos === 0 && neg > 0) severity += 25;          // nothing good said about it at all
  if (avgNegStar !== null && avgNegStar <= 2) severity += 15;  // furious, not mildly annoyed
  const severity_label = severity >= 50 ? "high" : (severity >= 30 ? "medium" : "low");

  // STALENESS. This engine reads every review a business has ever received, so a 2019
  // complaint arrives looking exactly as urgent as one from last month. Telling an owner
  // to fix something they fixed five years ago is how a report loses its credibility.
  // Computed here from real dates, not guessed by the writer.
  const STALE_MONTHS = 12;  // a full year with no recurrence is fair grounds to say "you may have fixed this"
  const negTimes = t.negative.map(n => n.created).filter(Boolean)
                             .map(d => new Date(d).getTime()).filter(n => !isNaN(n));
  const newestNeg = negTimes.length ? Math.max(...negTimes) : null;
  const monthsOld = newestNeg === null ? null
    : Math.floor((Date.now() - newestNeg) / (1000 * 60 * 60 * 24 * 30.44));
  const evidence_stale = monthsOld !== null && monthsOld >= STALE_MONTHS;

  return { theme: t.theme, total, positive: pos, negative: neg, mixed: mix,
           severity, severity_label,
           evidence_stale,
           newest_negative_at: newestNeg === null ? null : new Date(newestNeg).toISOString().slice(0,10),
           months_since_last_complaint: monthsOld,
           no_positive_offset: pos === 0 && neg > 0,
           avg_negative_stars: avgNegStar === null ? null : Math.round(avgNegStar * 10) / 10,
           minority_share: Math.round(share*100)/100,
           is_split, minority_negative,
           sample_positive: t.positive.slice(0,2), sample_negative: t.negative.slice(0,2),
           sample_mixed: t.mixed.slice(0,2) };
}).sort((a,b) => b.total - a.total);

// RECENT WINDOW. A lifetime average hides everything that matters about direction.
// A store can sit at 4.34 lifetime while that number is carried by years-old reviews; the recent
// years average 3.00. Without this split, the report congratulates a business that is sliding.
// This also disciplines the staleness rule: you cannot conclude a problem was fixed just
// because complaints stopped, if REVIEWS stopped. Silence is not evidence of repair.
const RECENT_MONTHS = 24;
const cutoff = Date.now() - RECENT_MONTHS * 30.44 * 24 * 60 * 60 * 1000;
const when = (r) => { const t = r.created ? new Date(r.created).getTime() : NaN; return isNaN(t) ? null : t; };
const dated  = rows.filter(r => when(r) !== null);
const recent = dated.filter(r => when(r) >= cutoff);
const prior  = dated.filter(r => when(r) <  cutoff);
const avgOf  = (arr) => {
  const s = arr.filter(r => typeof r.rating === "number");
  return s.length ? Math.round((s.reduce((a,r)=>a+r.rating,0)/s.length)*100)/100 : null;
};
const negCount = (arr) => arr.reduce((n,r) => n + (r.findings||[]).filter(f=>f.sentiment==="negative").length, 0);

const recent_avg = avgOf(recent), prior_avg = avgOf(prior);
const recent_window = {
  months: RECENT_MONTHS,
  reviews: recent.length,
  average_rating: recent_avg,
  low_star_reviews: recent.filter(r => typeof r.rating === "number" && r.rating <= 2).length,
  negative_findings: negCount(recent),
  prior_reviews: prior.length,
  prior_average_rating: prior_avg,
  rating_direction: (recent_avg !== null && prior_avg !== null)
    ? Math.round((recent_avg - prior_avg) * 100) / 100 : null,
  // Fewer than 10 reviews in two years, under one every two months, means we cannot tell a
  // fixed problem from a quiet one: a theme may simply never have come up again by chance.
  too_few_to_judge: recent.length < 10,
  newest_review_at: dated.length
    ? new Date(Math.max(...dated.map(when))).toISOString().slice(0,10) : null
};

const splits    = summary.filter(s => s.is_split);
const minority  = summary.filter(s => s.minority_negative)
                         .sort((a,b) => b.severity - a.severity);
const rated     = rows.filter(r => typeof r.rating === "number");
const avg       = rated.length ? (rated.reduce((s,r)=>s+r.rating,0)/rated.length) : null;

return [{ json: {
  reviews_analyzed: rows.length,
  parse_errors,
  average_rating: avg === null ? null : Math.round(avg*100)/100,
  themes: summary,
  splits,                       // genuine two-sided disagreements
  minority_flags: minority,     // lone complaints that must survive the summary
  has_contradictions: splits.length > 0,
  recent_window,
  source: rows[0] ? rows[0].source : "unknown"
}}];

const d = $json;
const PLAIN = { price_value:"pricing", product_quality:"product quality",
  stock_availability:"stock availability", staff_service:"staff service", wait_time:"wait times",
  shipping_delivery:"shipping", returns_warranty:"returns and warranty",
  expertise:"technical expertise", facility:"the store itself", communication:"communication" };
const word = k => PLAIN[k] || k;

// ---------- QUIET MONTH: written in code, no model call. ----------
// Most months are quiet. A fixed four-line template cannot hallucinate, costs nothing,
// and its shape tells the owner at a glance that there is nothing new to read.
if (d.report_type === 'quiet') {
  // A quiet month still has to tell the truth about direction. The earlier version printed
  // only the lifetime average, which is the exact number the full report proves is
  // misleading, so the tool would have spent eleven months undoing its own headline.
  const rw = d.recent_window || {};
  const top = (d.minority_flags || []).slice(0, 2)
    .map(f => `${word(f.theme)} (${f.negative} negative${f.positive ? `, ${f.positive} positive` : ", none positive"})`);

  const lines = [
    "NO NEW REVIEWS THIS MONTH",
    "",
    `All time: ${d.reviews_analyzed} reviews, ${d.average_rating} average.`
  ];

  if (rw.reviews !== undefined && rw.average_rating !== null && rw.average_rating !== undefined) {
    const dir = rw.rating_direction;
    const move = (dir === null || dir === undefined || dir === 0)
      ? "level with"
      : (dir < 0 ? `down ${Math.abs(dir)} from` : `up ${dir} from`);
    lines.push(`Last ${rw.months} months: ${rw.reviews} review${rw.reviews === 1 ? '' : 's'}, `
             + `${rw.average_rating} average, ${move} ${rw.prior_average_rating} before that.`);
  }
  if (rw.newest_review_at) {
    const months = Math.floor((Date.now() - new Date(rw.newest_review_at).getTime()) / (1000*60*60*24*30.44));
    lines.push(`Your most recent review is from ${rw.newest_review_at}, about ${months} months ago.`);
  }
  lines.push("");

  if (rw.too_few_to_judge) {
    lines.push("WORTH KNOWING", "",
      "Your all-time average is carried by older reviews. With so few recent ones, your store looks "
      + "quiet to anyone searching today, and there is not enough current feedback to tell whether "
      + "older problems have been resolved. Asking a few recent happy customers for a review is the "
      + "fastest way to fix both.", "");
  }

  if (top.length) {
    // blank line after the heading, or the email renderer treats heading+bullets
    // as one block and prints them as a run-on paragraph.
    lines.push("STILL OPEN", "", ...top.map(t => `- ${t}`), "");
  }
  lines.push("We keep reading every month. You only hear from us when something moves.");
  return [{ json: { ...d, prompt: null, quiet_digest: lines.join("\n") } }];
}

const facts = JSON.stringify({
  reviews_analyzed: d.reviews_analyzed,
  average_rating: d.average_rating,
  themes: d.themes,
  splits: d.splits,
  minority_flags: d.minority_flags,
  recent_window: d.recent_window
}, null, 1);

const c = d.comparison;
const isDelta = d.report_type === 'delta' && c;
const changeFacts = isDelta ? JSON.stringify({
  new_reviews_this_period: d.new_reviews,
  previous_total: c.previous_total,
  current_total: d.reviews_analyzed,
  previous_average: c.previous_average,
  current_average: d.average_rating,
  average_change: c.average_change,
  changed_themes: c.changed_themes,
  first_ever_positive_mentions: c.first_positive_mentions
}, null, 1) : null;

const prompt =
`You are writing a short feedback digest that is emailed DIRECTLY TO the owner and store manager
of an HVAC parts retailer. They are the reader. Address them as "you" and "your store". Never
write about them in the third person ("the owner should..."), because they are the one reading it.
Write as their IT partner reporting what customers said, not as an analyst describing a business.
You are given ALREADY-COMPUTED analysis. Do not recount, re-judge, or infer beyond it.

COMPUTED ANALYSIS:
${facts}
${isDelta ? `
WHAT CHANGED SINCE THE LAST REPORT:
${changeFacts}
` : ""}
HARD RULES:
${isDelta ? `- THIS IS A FOLLOW-UP REPORT. The owner already read the previous one. Lead with WHAT CHANGED. Do not re-explain findings that were unchanged; a repeated report is a report nobody opens.
- Spend most of the digest on the ${d.new_reviews} new review(s) and on themes in "changed_themes". Mention unchanged standing findings in one line at most.
- If "first_ever_positive_mentions" is not empty, say so plainly. A theme earning its first positive mention is the clearest sign something got fixed, and it is the most encouraging thing you can tell an owner.
- Only describe a change if it appears in the change data. Never infer improvement or decline from tone.` : `- THIS IS THE FIRST REPORT for this business. Cover the whole picture.`}
- ${d.has_contradictions
    ? "There ARE genuine disagreements (see \"splits\"). Give them their own section with the counts on each side. Do not average them into one lukewarm sentence."
    : "There are NO genuine disagreements in this batch. Say so plainly in one line. DO NOT invent, imply, or hint at a split. Inventing disagreement here would be a factual error."}
- "minority_flags" holds EVERY negative signal that is not part of a declared split, ALREADY SORTED WORST FIRST by a computed "severity" score. Lead with the highest severity. Every flag with severity_label "high" or "medium" MUST appear. You may group the "low" ones into a single closing line. A theme with "no_positive_offset": true means nothing good was ever said about it, which is worse than a higher raw count that is mostly positive.
- TREND FIRST: "recent_window" compares the last 24 months against everything before it. If
"rating_direction" is negative, the lifetime average is flattering them and you must say so
early and plainly, with both numbers. A business sliding from 4.8 to 3.0 needs to hear that
before it hears anything else. If the direction is positive, say that too, and mean it.
- REVIEW VOLUME: if "too_few_to_judge" is true, the store has had almost no reviews in two
years. Say this explicitly as a finding in its own right. A business with no recent reviews is
invisible to people searching for it, and it also means you CANNOT tell a fixed problem from a
quiet one. Recommend asking recent satisfied customers for reviews.
- RECENCY: every flag carries "newest_negative_at" (the date of its most recent complaint),
"months_since_last_complaint", and "evidence_stale". When a flag is stale, say so in plain words and
give the date of the most recent complaint. If "too_few_to_judge" is FALSE (they have had real
review volume since, with no recurrence), you may say it looks resolved and they can disregard.
If "too_few_to_judge" is TRUE, you must NOT say it looks resolved. Say instead that there has
not been enough recent feedback to tell, and that it may already be handled. Never present an
absence of complaints as proof of repair when there is an absence of reviews. Do not soften the finding, just date it honestly. An owner who fixed something
in 2019 should not be told to go fix it again in 2026. Where complaints are recent, say that too,
because "this happened last month" and "this happened six years ago" call for different urgency.
- Use only the counts given. Never state a number that is not in the analysis.
- CREDIBILITY: never assert a customer claim as established fact. One reviewer's account is a
report, not a finding. Write it as "one reviewer reports X" and name the record YOU CAN ASK THEM
to check it against (close-out times, the work ticket, the invoice). Where a claim cannot be
checked at all ("the owner does not care"), describe it as how that customer felt, never as
what happened. The owner knows their own business. One sentence they know to be false costs
you the credibility of the entire report.
- PARAPHRASE IS HELD TO THE SAME STANDARD AS A QUOTE. Never describe an OUTCOME the review
does not state. A customer predicting, threatening, or wishing for a consequence is not a
report that the consequence happened: "they will get caught up in court" is anger, NOT a
legal dispute. Do not upgrade a threat into an event, a worry into a fact, or an opinion
into a finding. If you cannot describe it without adding something the customer did not
say, quote them instead.
QUOTES MUST BE EXACT. If you put text in quotation marks it must be copied character for character from a "quote" field in the analysis. Do not reorder, trim, or rephrase inside quotation marks. If you cannot quote exactly, describe it without quotation marks.
- Plain English to a business owner. No buzzwords, no em dashes, use commas.
- PLAIN TEXT ONLY. No markdown. No asterisks for bold, no ## headings, no --- rules. Section headings in CAPS on their own line, list items starting with "- ". This gets emailed as plain text.
- NEVER print raw theme keys. They are internal identifiers. Write them as normal words: price_value -> pricing, product_quality -> product quality, stock_availability -> stock availability, staff_service -> staff service, wait_time -> wait times, shipping_delivery -> shipping, returns_warranty -> returns and warranty, expertise -> technical expertise, facility -> the store itself, communication -> communication.
- End with 2-3 concrete action items, each tied to a specific theme.

Format:
${isDelta ? `WHAT CHANGED
<2-4 sentences on the new reviews and any moved themes>

` : ""}WHAT CUSTOMERS SAID
<3-5 sentences>

${d.has_contradictions ? "WHERE THEY DISAGREE\n<one bullet per split, with counts on each side>" : "DISAGREEMENTS\n<one line stating there were none>"}

WORTH A CLOSER LOOK
<minority complaints worst first, or "none" if the list is empty>

DO THIS NEXT
<2-3 bullets>`;
return [{ json: { ...d, prompt, quiet_digest: null } }];

const a = $('Aggregate + Detect Splits').first().json;
const j = $input.first().json;
const grab = (x) => {
  if (typeof x === "string") return x;
  if (Array.isArray(x?.content)) return x.content.map(c => c?.text || "").join("");
  return x?.content?.[0]?.text || x?.text || x?.output || "";
};
const bp = $('Build Digest Prompt').first().json;
// A quiet month never goes near the model; its digest was built in code upstream.
const digest = bp.quiet_digest ? bp.quiet_digest : String(grab(j) || "").trim();

// Self-check: did the writer obey the no-invented-conflict rule?
const claimsDisagreement = /disagree|conflict|split|some customers.*(while|but|others)/i.test(digest);
const violation = !a.has_contradictions && /WHERE THEY DISAGREE/i.test(digest);

// QUOTE DRIFT CHECK: every quoted string in the finished digest must appear verbatim
// in some source review. Trailing punctuation placed inside the closing quote mark is
// allowed (normal typography); anything else is the writer paraphrasing inside quotes.
const canon = (s) => String(s == null ? "" : s)
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/\s+/g, " ")
  .trim();
const sources = canon($('Union Stored + New').all().map(i => i.json.text || "").join(" ||| "));
const quoted = (digest.match(/"[^"]{4,160}"/g) || []).map(q => q.slice(1, -1));
const drifted = quoted.filter(q => {
  const c = canon(q).replace(/[.,;:!?]+$/, "");
  return !sources.includes(c);
});

// Carry the comparison fields through; the email and the saved report row both need them.
const cmp = $('Compare To Last Report').first().json;
return [{ json: {
  digest,
  recent_window: a.recent_window,
  report_type: cmp.report_type,
  new_reviews: cmp.new_reviews,
  comparison: cmp.comparison,
  theme_counts: cmp.theme_counts,
  business_name: cmp.business_name,
  location_id: cmp.location_id,
  period_label: cmp.report_type === 'quiet' ? 'No new reviews'
    : (cmp.report_type === 'delta' ? `${cmp.new_reviews} new review${cmp.new_reviews === 1 ? '' : 's'}`
    : `All ${cmp.reviews_analyzed} reviews`),
  flag_count: (a.minority_flags || []).length,
  reviews_analyzed: a.reviews_analyzed,
  average_rating: a.average_rating,
  had_real_contradictions: a.has_contradictions,
  split_count: (a.splits || []).length,
  minority_flag_count: (a.minority_flags || []).length,
  parse_errors: a.parse_errors,
  source: a.source,
  QA_invented_conflict: violation,
  QA_quotes_checked: quoted.length,
  QA_quote_drift: drifted.length > 0,
  QA_drifted_quotes: drifted,
  QA_note: violation
    ? "FAIL: no real split existed but the digest published a disagreement section."
    : "ok"
}}];

// Renders the plain-text digest into a branded HTML email.
// The LLM writes prose only. All markup is built here, so nothing it emits can break layout.
const d = $json;
const esc = s => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const NAVY='#0B2545', ACCENT='#1D7A8C', INK='#1f2933', MUTED='#6b7785', LINE='#e3e8ee';
const blocks = String(d.digest || '').split(/\n\s*\n/).map(b => b.trim()).filter(Boolean);
let body = '';
for (const b of blocks) {
  // A heading is a short ALL-CAPS line with no leading bullet.
  if (/^[A-Z][A-Z0-9 ,'&/-]{2,60}$/.test(b) && !b.startsWith('-')) {
    body += `<h2 style="margin:26px 0 10px;font:600 13px/1.4 Arial,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:${ACCENT};border-bottom:1px solid ${LINE};padding-bottom:6px;">${esc(b)}</h2>`;
  } else if (b.startsWith('-')) {
    const items = b.split('\n').filter(l => l.trim().startsWith('-'))
      .map(l => `<li style="margin:0 0 11px;">${esc(l.replace(/^\s*-\s*/,''))}</li>`).join('');
    body += `<ul style="margin:0 0 14px;padding-left:20px;font:400 15px/1.62 Arial,sans-serif;color:${INK};">${items}</ul>`;
  } else {
    body += `<p style="margin:0 0 14px;font:400 15px/1.62 Arial,sans-serif;color:${INK};">${esc(b)}</p>`;
  }
}


// Month-over-month strip. Only rendered when there is a real prior report to compare to.
const c = d.comparison;
const arrow = (n) => n > 0 ? '▲' : (n < 0 ? '▼' : '–');
const tone  = (n, goodUp) => n === 0 ? MUTED : ((n > 0) === goodUp ? '#1a7f5a' : '#b4232a');
let cmpStrip = '';
if (c && d.report_type !== 'quiet') {   // the quiet header already says it
  const bits = [];
  bits.push(`<span style="color:${tone(c.total_change, true)};">${arrow(c.total_change)} ${Math.abs(c.total_change)} new review${Math.abs(c.total_change) === 1 ? '' : 's'}</span>`);
  if (c.average_change !== null) {
    bits.push(`<span style="color:${tone(c.average_change, true)};">${arrow(c.average_change)} ${c.average_change === 0 ? 'rating unchanged' : Math.abs(c.average_change).toFixed(2) + ' rating'}</span>`);
  }
  if ((c.first_positive_mentions || []).length) {
    bits.push(`<span style="color:#1a7f5a;font-weight:600;">first positive mention: ${esc(c.first_positive_mentions.join(', ').replace(/_/g,' '))}</span>`);
  }
  cmpStrip = `<tr><td style="padding:10px 28px;background:#f2f7f9;border-bottom:1px solid ${LINE};font:400 13px/1.5 Arial,sans-serif;color:${INK};">
    <strong style="color:${NAVY};">Since last report:</strong> ${bits.join(' &nbsp;&middot;&nbsp; ')}
  </td></tr>`;
}

const stat = (n,l) => `<td align="center" style="padding:12px 8px;"><div style="font:700 22px/1 Arial,sans-serif;color:${NAVY};">${esc(n)}</div><div style="font:400 11px/1.4 Arial,sans-serif;color:${MUTED};text-transform:uppercase;letter-spacing:.06em;margin-top:4px;">${esc(l)}</div></td>`;

const html = `<!doctype html><html><body style="margin:0;padding:0;background:#f4f6f8;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f6f8;padding:24px 12px;"><tr><td align="center">
<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid ${LINE};">
  <tr><td style="background:${NAVY};padding:22px 28px;">
    <div style="font:700 19px/1.3 Arial,sans-serif;color:#ffffff;">Review Intelligence</div>
    <div style="font:400 13px/1.4 Arial,sans-serif;color:#9fb3c8;margin-top:3px;">${esc(d.business_name || 'Your business')} &nbsp;&middot;&nbsp; ${esc(d.period_label || 'Latest reviews')}</div>
  </td></tr>
  ${cmpStrip}
  <tr><td style="padding:4px 20px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-bottom:1px solid ${LINE};"><tr>
    ${stat(d.reviews_analyzed, 'Reviews read')}
    ${stat(d.average_rating, 'Avg all time')}
    ${(d.recent_window && d.recent_window.average_rating !== null && d.recent_window.average_rating !== undefined)
        ? stat(d.recent_window.average_rating, 'Avg last 24mo') : ''}
    ${stat(d.split_count, 'Real splits')}
    ${stat(d.flag_count, 'Needs a look')}
  </tr></table></td></tr>
  <tr><td style="padding:6px 28px 26px;">${body}</td></tr>
  <tr><td style="background:#f8fafb;border-top:1px solid ${LINE};padding:16px 28px;font:400 12px/1.6 Arial,sans-serif;color:${MUTED};">
    Generated from ${esc(d.reviews_analyzed)} Google reviews. Every quote is verbatim. Themes are counted in code, not estimated.<br>
    <span style="color:${NAVY};font-weight:600;">Your Company</span> &nbsp;&middot;&nbsp; Review Intelligence
  </td></tr>
</table></td></tr></table></body></html>`;

return [{ json: { ...d, email_html: html, email_subject: `Review Intelligence: ${d.business_name || 'your business'} (${d.reviews_analyzed} reviews, ${d.average_rating}★)` } }];

const CFG = $('Run Config').first().json;
const LOCATION_ID = CFG.location_id;
const BUSINESS_NAME = CFG.business_name;
// Classify-once gate. Anything already in review_classifications is never sent to the model
// again, which is what makes the numbers stable: LLM output drifts run to run even at
// temperature 0, so the only reliable fix is to stop asking twice.
const stored = new Set(
  $input.all().map(i => i.json && i.json.review_id).filter(Boolean)
);
const fresh = $('Normalize Reviews').all()
  .map(i => i.json)
  .filter(r => r.review_id && !stored.has(r.review_id))
  .map(r => ({ json: { ...r, location_id: LOCATION_ID, business_name: BUSINESS_NAME } }));
console.log(`already stored: ${stored.size} | to classify: ${fresh.length}`);
return fresh;   // may be empty; the IF node downstream routes that case

const CFG = $('Run Config').first().json;
const LOCATION_ID = CFG.location_id;
const BUSINESS_NAME = CFG.business_name;
// One request, all rows. PostgREST takes an array body.
const src = $('Select Unclassified').all().map(i => i.json);
const rows = $input.all().map((item, i) => {
  const j = item.json, s = src[i] || {};
  return {
    location_id: LOCATION_ID,
    business_name: BUSINESS_NAME,
    review_id: j.review_id,
    star_rating: j.rating ?? null,
    reviewer_name: j.author ?? null,
    review_text: j.text ?? null,
    review_created_at: s.created ?? null,
    themes: j.findings || [],
    model: "claude-sonnet-4-6"
  };
}).filter(r => r.review_id);
return [{ json: { rows, count: rows.length } }];

// Rebuild the full classification set: everything previously stored, plus anything
// classified on this run. Reports count THESE rows. Nothing is re-derived from a model.
const toParseShape = (row) => ({
  review_id: row.review_id,
  rating: row.star_rating ?? null,
  text: row.review_text ?? "",
  author: row.reviewer_name ?? "anonymous",
  source: "storage",
  created: row.review_created_at ?? null,
  findings: Array.isArray(row.themes) ? row.themes : [],
  parse_error: null
});

const byId = new Map();
for (const it of $('Fetch Stored').all()) {
  const r = it.json;
  if (r && r.review_id) byId.set(r.review_id, toParseShape(r));
}
let added = 0;
try {
  for (const it of $('Parse Classification').all()) {
    const r = it.json;
    if (r && r.review_id) { byId.set(r.review_id, r); added++; }
  }
} catch (e) { /* quiet month: the classify branch never ran */ }

const all = [...byId.values()];
console.log(`classifications in play: ${all.length} (newly classified this run: ${added})`);
if (!all.length) throw new Error("No classifications available to report on.");
return all.map(json => ({ json }));

// Month-over-month. The previous report's theme_counts snapshot is the baseline;
// everything here is arithmetic against it, so the comparison cannot be invented.
const agg = $json;
const prevRows = $('Fetch Last Report').all().map(i => i.json).filter(r => r && r.id);
const prev = prevRows.length ? prevRows[0] : null;

let new_reviews = 0;
try { new_reviews = $('Parse Classification').all().length; } catch (e) {}

const theme_counts = {};
for (const s of (agg.themes || [])) {
  theme_counts[s.theme] = { positive: s.positive, negative: s.negative, mixed: s.mixed };
}

const report_type = !prev ? 'full' : (new_reviews > 0 ? 'delta' : 'quiet');

let comparison = null;
if (prev) {
  const pc = prev.theme_counts || {};
  const changed = [];
  for (const [theme, now] of Object.entries(theme_counts)) {
    const was = pc[theme] || { positive: 0, negative: 0 };
    const dp = now.positive - (was.positive || 0);
    const dn = now.negative - (was.negative || 0);
    if (dp || dn) changed.push({ theme, positive_change: dp, negative_change: dn,
                                 now_positive: now.positive, now_negative: now.negative });
  }
  // A theme going from zero positive to its first positive is the single most
  // meaningful movement a business owner can be told. Surface it explicitly.
  const first_positive = changed.filter(c => c.positive_change > 0 &&
                                             (pc[c.theme]?.positive || 0) === 0).map(c => c.theme);
  comparison = {
    previous_report_at: prev.created_at,
    previous_total: prev.reviews_total,
    previous_average: prev.average_rating === null ? null : Number(prev.average_rating),
    total_change: agg.reviews_analyzed - (prev.reviews_total || 0),
    average_change: (prev.average_rating != null && agg.average_rating != null)
      ? Math.round((agg.average_rating - Number(prev.average_rating)) * 100) / 100 : null,
    changed_themes: changed,
    first_positive_mentions: first_positive
  };
}

return [{ json: { ...agg, report_type, new_reviews, theme_counts, comparison,
                  location_id: $('Run Config').first().json.location_id, business_name: $('Run Config').first().json.business_name } }];

// SINGLE SOURCE OF TRUTH for which business this run belongs to.
// Two reasons this exists:
//  1) Test runs must NEVER write fake reviews into a real client's stored history.
//     Every test set gets its own location_id, so prod data cannot be polluted.
//  2) Everything downstream reads location_id from here, so pointing this workflow at
//     a different client is a one-line change instead of hunting four hardcoded copies.
const LIVE = {
  location_id:   "locations/YOUR_GBP_LOCATION_ID",
  business_name: "Your Business Name"
};

const first = $input.first().json || {};
const src = String(first.source || "");
const isTest = src.startsWith("TEST");

const cfg = isTest
  ? { location_id: "TEST/" + src.replace(/^TEST:?/, ""), business_name: "TEST " + src.replace(/^TEST:?/, "") }
  : LIVE;

console.log(`run config -> ${cfg.location_id} (${isTest ? "TEST, isolated" : "LIVE CLIENT DATA"})`);
return $input.all().map(i => ({ json: { ...i.json, ...cfg, is_test: isTest } }));
